ReplacementContent:
{sortedFlat.map(card => {
  if (card.id === 'pe_ratio' || card.id === 'forward_pe') return null;
  return (
    <FundamentalCard
      key={card.id}
      card={card}
      onClick={() => onCardClick(card)}
    />
  );
})}

